import httpxfrom datetime import datetimefrom sqlalchemy.orm import Sessionfrom app import crudfrom app.models import City, Temperatureasync def get_city_coordinates(city_name: str) -> tuple[float, float] | None:    url = "https://geocoding-api.open-meteo.com/v1/search"    async with httpx.AsyncClient() as client:        response = await client.get(            url,            params={                "name": city_name,                "count": 1,                "language": "en-US",                "format": "json"            }        )        response.raise_for_status()        data = response.json()        results = data.get("results")        if not results:            return None        latitude = results[0]["latitude"]        longitude = results[0]["longitude"]        return latitude, longitudeasync def get_city_temperature(longitude: float, latitude: float) -> float:    url = "https://api.open-meteo.com/v1/forecast"    async with httpx.AsyncClient() as client:        response = await client.get(            url,            params={                "latitude": latitude,                "longitude": longitude,                "current": "temperature_2m"            }        )        response.raise_for_status()        data = response.json()        temperature = data["current"]["temperature_2m"]        return temperatureasync def update_city_temperatures(db: Session, cities: list[City]) -> list[Temperature]:    temperature_records: list[Temperature] = []    for city in cities:        coordinates = await get_city_coordinates(city.name)        if coordinates is None:            continue        latitude, longitude = coordinates        temperature = await get_city_temperature(longitude, latitude)        temperature_record = crud.create_temperature(            db=db,            city_id=city.id,            temperature=temperature        )        temperature_records.append(temperature_record)    return temperature_records